import sys

def main():
    s = sys.stdin.readline().strip()
    t = sys.stdin.readline().strip()

    n = len(s)
    chars = list(s)

    i = n - 1
    while i >= 0:
        if chars[i] < 'z':
            chars[i] = chr(ord(chars[i]) + 1)
            break
        else:
            chars[i] = 'a'
            i -= 1

    result = "".join(chars)

    if result > s and result < t:
        print(result)
    else:
        print("No such string")

if __name__ == "__main__":
    main()
